from collections import defaultdict
def dihs(M):
    M=[list(r) for r in M]; n=len(M); out=set()
    cur=M
    for _ in range(2):
        for V in (cur,[list(r) for r in zip(*cur)][::-1] if False else [list(r) for r in zip(*cur)]):
            key=tuple(tuple(v for v in row) for row in V)
            out.add(key)
        cur=[r[::-1] for r in cur]
    return list(out)
